const PAPERS=[
{"t": "Prospect Theory: An Analysis of Decision under Risk", "a": "Kahneman & Tversky", "y": 1979, "s": ["decision-quality", "belief-elicitation", "risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Dominant descriptive model of risky choice. Reference dependence, S-shaped value function, and probability weighting remain the framework most applied work builds on.", "q": "The λ≈2.25 loss aversion estimate shows more heterogeneity than textbooks suggest. Salience theory offers a competing mechanism for several core phenomena.", "u": "content/papers/kahneman-tversky-1979.html"},
{"t": "Cumulative Prospect Theory", "a": "Tversky & Kahneman", "y": 1992, "s": ["decision-quality"], "ev": "strong", "st": "canonical", "v": "Parametric extension to multi-outcome prospects. Provides the functional forms used in most quantitative applications.", "q": "Parameter estimates vary considerably across studies.", "u": "content/papers/tversky-1992.html"},
{"t": "A meta-analysis of loss aversion in risky contexts", "a": "Walasek, Mullett & Stewart", "y": 2024, "s": ["decision-quality"], "ev": "mixed", "st": "debated", "v": "Meta-analysis of CPT λ from individual-level data. Median λ=1.31 [1.10, 1.53] — lower than the canonical 2.25.", "q": "Only 17 studies with available raw data. A separate meta-analysis (Brown et al., 2024) found λ≈1.96 across 607 estimates.", "u": "content/papers/walasek-2024.html"},
{"t": "Meta-analysis of Empirical Estimates of Loss Aversion", "a": "Brown, Imai, Vieider & Camerer", "y": 2024, "s": ["decision-quality"], "ev": "strong", "st": "debated", "v": "Largest meta-analysis of loss aversion: 607 estimates, mean λ≈1.96 [1.82, 2.10]. Substantial heterogeneity across domains and methods.", "q": "A re-meta-analysis (Yechiam et al., 2025) found λ drops to ~1.07 when stimulus asymmetry and ordering are controlled.", "u": "content/papers/brown-2024.html"},
{"t": "Loss aversion is not robust: A re-meta-analysis", "a": "Yechiam, Zeif & Ashby", "y": 2025, "s": ["decision-quality"], "ev": "mixed", "st": "emerging", "v": "When stimulus asymmetry and ordering effects are controlled, loss aversion nearly vanishes (λ≈1.07).", "q": "Uses a subset of the Brown et al. data. The moderators may themselves be debatable methodological choices.", "u": "content/papers/yechiam-2025.html"},
{"t": "Looming Large or Seeming Small? Loss Attitudes in a Representative Sample", "a": "Chapman, Snowberg, Wang & Camerer", "y": 2025, "s": ["decision-quality"], "ev": "mixed", "st": "emerging", "v": "Representative-sample study finding 47-57% of participants are loss-tolerant (λ≤1). Challenges the universality of loss aversion.", "q": "Novel elicitation method (DOSE) may produce different estimates than standard approaches.", "u": "content/papers/chapman-2025.html"},
{"t": "Salience Theory of Choice Under Risk", "a": "Bordalo, Gennaioli & Shleifer", "y": 2012, "s": ["decision-quality", "attention-salience"], "ev": "mixed", "st": "debated", "v": "Attention-based alternative to probability weighting. If correct, display redesign can reduce choice anomalies without retraining.", "q": "Empirical track record shorter than prospect theory. Divergent predictions are difficult to test with natural data.", "u": "content/papers/bordalo-2012.html"},
{"t": "Cognitive Uncertainty", "a": "Enke & Graeber", "y": 2023, "s": ["decision-quality", "attention-salience"], "ev": "weak", "st": "emerging", "v": "People are uncertain about their own valuations and compress toward defaults. Potentially unifies many anomalies as noise rather than stable biases.", "q": "Tested in a limited set of domains. Needs broader replication.", "u": "content/papers/enke-2023.html"},
{"t": "Reference-Dependent Preferences and the Observed Violations of Expected Utility", "a": "Kőszegi & Rabin", "y": 2006, "s": ["decision-quality"], "ev": "strong", "st": "canonical", "v": "Endogenized the reference point using rational expectations, connecting prospect theory to equilibrium economics.", "q": "Assumes rational expectations within a bounded-rationality model — a conceptual tension.", "u": "content/papers/kszegi-2006.html"},
{"t": "Regret Theory", "a": "Loomes & Sugden", "y": 1982, "s": ["decision-quality"], "ev": "mixed", "st": "debated", "v": "Anticipated regret explains independence violations without reference-dependent value functions.", "q": "Applies only when the unchosen option's outcome is visible.", "u": "content/papers/loomes-1982.html"},
{"t": "Calibration of Probabilities: The State of the Art to 1980", "a": "Lichtenstein, Fischhoff & Phillips", "y": 1982, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Established overconfidence as robust: 90% CIs contain truth ~50% of the time. Replicated across domains.", "q": "Ecological rationality critique qualified the severity. Item selection effects explain part of the pattern.", "u": "content/papers/lichtenstein-1982.html"},
{"t": "Overconfidence in interval estimates", "a": "Soll & Klayman", "y": 2004, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Identified anchoring-and-adjustment as the mechanism for narrow confidence intervals.", "q": "Explains the process failure but not all overconfidence patterns.", "u": "content/papers/soll-2004.html"},
{"t": "Probabilistic mental models: A Brunswikian theory of confidence", "a": "Gigerenzer, Hoffrage & Kleinbölting", "y": 1991, "s": ["belief-elicitation"], "ev": "strong", "st": "debated", "v": "Ecological challenge: apparent miscalibration partly reflects experimenters selecting hard, unrepresentative questions.", "q": "Does not eliminate overconfidence entirely. Real-world miscalibration persists in many professional domains.", "u": "content/papers/gigerenzer-1991.html"},
{"t": "Superforecasting", "a": "Tetlock & Gardner", "y": 2015, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Calibration is trainable. A subset of forecasters are consistently well-calibrated, and their methods can be taught.", "q": "Selection effects may partly explain superforecaster performance. Domain transfer is weak.", "u": "content/papers/tetlock-2015.html"},
{"t": "Prediction and Judgment: Why Superforecasting Works", "a": "Mellers, Stone, Atanasov et al.", "y": 2015, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Formal analysis of the Good Judgment Project. Decomposition, base-rate thinking, and granular updating characterize the best performers.", "q": "Tournament structure may not generalize to real-world forecasting.", "u": "content/papers/mellers-2015.html"},
{"t": "Graphical Distribution Builders for Non-Expert Elicitation", "a": "Goldstein & Rothschild", "y": 2014, "s": ["belief-elicitation"], "ev": "mixed", "st": "debated", "v": "Non-experts can construct full subjective distributions using interactive graphical tools.", "q": "Lab-confined. Cognitive load is substantial. Sensitive to design parameters.", "u": "content/papers/goldstein-2014.html"},
{"t": "Linguistic Probabilities: Variability in Verbal Probability Expressions", "a": "Wallsten, Budescu, Rapoport & Zwick", "y": 1986, "s": ["belief-elicitation", "uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "'Likely' means 0.55 to 0.90 depending on the person. Foundational documentation of verbal probability variability.", "q": "Well-documented but unsolved. Hybrid verbal-numeric formats are the best available mitigation.", "u": "content/papers/wallsten-1986.html"},
{"t": "Strictly Proper Scoring Rules, Prediction, and Estimation", "a": "Gneiting & Raftery", "y": 2007, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Unified the theory of proper scoring rules for probabilistic forecasts. Introduced the CRPS. Essential mathematical reference.", "q": "Properness assumes expected utility, undermined by prospect theory's probability weighting.", "u": "content/papers/gneiting-2007.html"},
{"t": "How to Improve Bayesian Reasoning Without Instruction: Frequency Formats", "a": "Gigerenzer & Hoffrage", "y": 1995, "s": ["uncertainty-communication", "belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Natural frequencies raise correct Bayesian inference from ~15% to ~50%. Format causally affects reasoning.", "q": "Benefit strongest for multi-step Bayesian problems. The evolved-processor interpretation is debated.", "u": "content/papers/gigerenzer-hoffrage-1995.html"},
{"t": "Interpreting IPCC Probabilistic Statements Around the World", "a": "Budescu, Broomell & Por", "y": 2009, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Even standardized verbal probability scales are misinterpreted ~40% of the time by readers.", "q": "Adding numeric ranges significantly improves interpretation (Budescu et al., 2014).", "u": "content/papers/budescu-2009.html"},
{"t": "Effective Communication of Uncertainty in the IPCC Reports", "a": "Budescu, Por, Broomell & Smithson", "y": 2014, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Hybrid verbal-numeric formats outperform verbal-only or numeric-only for interpretation accuracy.", "q": "Tested primarily in climate communication. Generalization to other domains assumed.", "u": "content/papers/budescu-2014.html"},
{"t": "Uncertainty Visualization: A Cognitive Framework", "a": "Padilla, Kay & Hullman", "y": 2022, "s": ["uncertainty-communication"], "ev": "mixed", "st": "emerging", "v": "Connects uncertainty display design to perceptual and cognitive mechanisms.", "q": "Framework, not a set of tested interventions.", "u": "content/papers/padilla-2022.html"},
{"t": "Hypothetical Outcome Plots", "a": "Hullman, Resnick & Adar", "y": 2015, "s": ["uncertainty-communication", "sampling-experience"], "ev": "mixed", "st": "debated", "v": "Animated uncertainty displays converting statistical reading into frequency estimation.", "q": "Lab evidence is positive for comparison tasks. Sensitive to animation parameters.", "u": "content/papers/hullman-2015.html"},
{"t": "Quantile Dotplots for Visualizing Uncertainty", "a": "Kay, Kola, Hullman & Munson", "y": 2016, "s": ["uncertainty-communication", "sampling-experience"], "ev": "mixed", "st": "debated", "v": "Bridges frequency-based reasoning with distributional display. Improved decision quality vs. density plots.", "q": "Requires brief onboarding for unfamiliar users.", "u": "content/papers/kay-2016.html"},
{"t": "Prediction, Judgment, and Complexity", "a": "Hofman, Goldstein & Hullman", "y": 2020, "s": ["uncertainty-communication", "decision-quality"], "ev": "mixed", "st": "debated", "v": "Demonstrated the comprehension-use gap: display rankings by comprehension and decision quality can diverge.", "q": "Evidence base thinner than the frequency literature. May be task-specific.", "u": "content/papers/hofman-2020.html"},
{"t": "Visual Aids and Medical Risk Communication", "a": "Garcia-Retamero & Cokely", "y": 2013, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Icon arrays substantially improve risk understanding across numeracy levels, especially for low-numeracy users.", "q": "Primarily medical risk. Less established for non-binary distributional uncertainty.", "u": "content/papers/garcia-retamero-2013.html"},
{"t": "How People Interpret Probabilistic Weather Forecasts", "a": "Gigerenzer, Hertwig et al.", "y": 2005, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Public misinterprets 'probability of precipitation' depending on implicit reference class: time, area, or forecaster agreement.", "q": "Demonstrates chronic misunderstanding of even the most commonly communicated probability.", "u": "content/papers/gigerenzer-2005.html"},
{"t": "Numeracy and Decision Making", "a": "Peters, Västfjäll, Slovic et al.", "y": 2006, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Numeracy changes the nature of processing, not just comprehension. High-numeracy individuals extract more affective meaning from numbers.", "q": "Measured with short scales that may miss domain-specific numerical facility.", "u": "content/papers/peters-2006.html"},
{"t": "How Well Do Researchers Understand Confidence Intervals?", "a": "Hoekstra, Morey, Rouder & Wagenmakers", "y": 2014, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Majority of researchers endorse incorrect CI interpretations.", "q": "Functional impact may be smaller if users treat CIs as rough uncertainty signals.", "u": "content/papers/hoekstra-2014.html"},
{"t": "Error Bar Misinterpretation", "a": "Belia, Fidler, Williams & Cumming", "y": 2005, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Many published scientists cannot correctly determine whether overlapping error bars indicate significance.", "q": "Explicit labeling and education may help, but the format remains inherently misleading for non-experts.", "u": "content/papers/belia-2005.html"},
{"t": "Uncertainty Forecasts Improve Decisions", "a": "Joslyn & LeClerc", "y": 2012, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Providing forecast uncertainty ranges improved protective action decisions compared to point forecasts.", "q": "Weather domain. Generalization to AI uncertainty assumed.", "u": "content/papers/joslyn-2012.html"},
{"t": "A Sparsity-Based Model of Bounded Rationality", "a": "Gabaix", "y": 2014, "s": ["attention-salience"], "ev": "strong", "st": "canonical", "v": "Agents optimally allocate limited attention by attending to a sparse set of factors.", "q": "Empirical applications still emerging. Predictions hard to test in naturalistic settings.", "u": "content/papers/gabaix-2014.html"},
{"t": "Nudge", "a": "Thaler & Sunstein", "y": 2008, "s": ["attention-salience"], "ev": "strong", "st": "canonical", "v": "Synthesized the choice architecture literature. Default effects, salience, and framing reliably shift behavior.", "q": "Nudge effects are typically modest. Default effects are the most reliable.", "u": "content/papers/thaler-2008.html"},
{"t": "Risk, Ambiguity, and the Savage Axioms", "a": "Ellsberg", "y": 1961, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "People prefer known risks to unknown ones, even when the unknown could be better. Foundational demonstration of ambiguity aversion.", "q": "Ambiguity attitudes vary by domain, probability level, and individual.", "u": "content/papers/ellsberg-1961.html"},
{"t": "Ambiguity and Comparative Ignorance", "a": "Fox & Tversky", "y": 1995, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Willingness to bet depends on perceived competence relative to the uncertainty source.", "q": "Hard to parameterize. More descriptive than predictive.", "u": "content/papers/fox-1995.html"},
{"t": "Maxmin Expected Utility with Non-Unique Prior", "a": "Gilboa & Schmeidler", "y": 1989, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Evaluate prospects by the worst-case prior. Axiomatically clean model of extreme ambiguity aversion.", "q": "Too conservative for moderate ambiguity.", "u": "content/papers/gilboa-1989.html"},
{"t": "Risk as Feelings", "a": "Loewenstein, Weber, Hsee & Welch", "y": 2001, "s": ["risk-ambiguity", "uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Emotional reactions to risk diverge from cognitive assessments and often dominate decisions.", "q": "Integration with formal decision models remains incomplete.", "u": "content/papers/loewenstein-2001.html"},
{"t": "Myopic Loss Aversion and the Equity Premium Puzzle", "a": "Benartzi & Thaler", "y": 1995, "s": ["temporal-dynamics", "decision-quality"], "ev": "strong", "st": "canonical", "v": "Evaluation frequency × loss aversion explains the equity premium puzzle. Cleanest design implication in this archive.", "q": "Most evidence is from financial contexts. Generalization to non-financial settings assumed.", "u": "content/papers/benartzi-thaler-1995.html"},
{"t": "An Experiment on Risk Taking and Evaluation Periods", "a": "Gneezy & Potters", "y": 1997, "s": ["temporal-dynamics"], "ev": "strong", "st": "canonical", "v": "Experimental confirmation: subjects seeing outcomes every period invested ~40% less in risky options.", "q": "Lab experiment with simple gambles.", "u": "content/papers/gneezy-1997.html"},
{"t": "Myopic Loss Aversion Among Professional Traders", "a": "Haigh & List", "y": 2005, "s": ["temporal-dynamics"], "ev": "mixed", "st": "debated", "v": "Professional traders also show myopic loss aversion. Expertise does not eliminate the effect.", "q": "Small sample. Needs broader replication with professional populations.", "u": "content/papers/haigh-2005.html"},
{"t": "Decisions From Experience and the Effect of Rare Events", "a": "Hertwig, Barron, Weber & Erev", "y": 2004, "s": ["sampling-experience", "uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Described and experienced probabilities produce opposite rare-event biases.", "q": "Fox & Hadar (2006) showed much of the gap is sampling error. A residual gap persists but is smaller.", "u": "content/papers/hertwig-2004.html"},
{"t": "The Description-Experience Gap in Risky Choice", "a": "Hertwig & Erev", "y": 2009, "s": ["sampling-experience"], "ev": "strong", "st": "canonical", "v": "Comprehensive review establishing the description-experience gap as a robust research program.", "q": "The mechanism debate (sampling error vs. processing mode) remained unresolved.", "u": "content/papers/hertwig-2009.html"},
{"t": "Decisions from Experience Without Feedback", "a": "Fox & Hadar", "y": 2006, "s": ["sampling-experience"], "ev": "mixed", "st": "debated", "v": "Much of the description-experience gap disappears when controlling for information actually received.", "q": "Camilleri & Newell (2011) found a residual gap even after controlling for sample information.", "u": "content/papers/fox-2006.html"},
{"t": "Distribution Display Changes Investment Behavior", "a": "Goldstein, Johnson & Sharpe", "y": 2008, "s": ["sampling-experience", "uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Showing full retirement outcome distributions changed investor behavior, making people more conservative.", "q": "More granular displays are more informative but more cognitively demanding.", "u": "content/papers/goldstein-2008.html"},
{"t": "Algorithm Aversion", "a": "Dietvorst, Simmons & Massey", "y": 2015, "s": ["ai-agents"], "ev": "strong", "st": "canonical", "v": "Seeing an algorithm fail reduces reliance below rational levels, even when the algorithm outperforms humans on average.", "q": "The aversion framing oversimplifies. Recent work treats this as context-sensitive trust calibration.", "u": "content/papers/dietvorst-2015.html"},
{"t": "Algorithm Appreciation", "a": "Logg, Minson & Moore", "y": 2019, "s": ["ai-agents"], "ev": "mixed", "st": "debated", "v": "People over-rely on algorithms for objective-seeming tasks. Direction depends on perceived task subjectivity.", "q": "The appreciation-aversion direction is context-dependent, not a stable individual trait.", "u": "content/papers/logg-2019.html"},
{"t": "Human-AI Complementarity in AI-Advised Decision Making", "a": "Bansal, Wu, Zhou et al.", "y": 2021, "s": ["ai-agents", "attention-salience"], "ev": "strong", "st": "canonical", "v": "Complementarity requires humans to identify when the AI is wrong — the task humans are worst at in most studied contexts.", "q": "Most studies use classification with known ground truth. Generalization to genuine uncertainty is less clear.", "u": "content/papers/bansal-2021.html"},
{"t": "Bayesian Models of Human-AI Integration", "a": "Steyvers, Tejeda, Kerrigan & Smyth", "y": 2022, "s": ["ai-agents"], "ev": "mixed", "st": "debated", "v": "Bayesian model predicting when combined judgment beats either source.", "q": "Assumes uncorrelated errors and calibrated confidence — rarely met in practice.", "u": "content/papers/steyvers-2022.html"},
{"t": "The Principles and Limits of Algorithm-in-the-Loop Decision Making", "a": "Green & Chen", "y": 2019, "s": ["ai-agents"], "ev": "mixed", "st": "debated", "v": "AI recommendations improve decisions on average but introduce new biases. Users anchor on AI advice.", "q": "Tested in pretrial risk assessment — a domain with ethical complications.", "u": "content/papers/green-2019.html"},
{"t": "To Trust or to Think: Cognitive Forcing Functions Reduce Overreliance", "a": "Buçinca, Malaya & Gajos", "y": 2021, "s": ["ai-agents", "attention-salience"], "ev": "mixed", "st": "debated", "v": "Requiring users to commit to a judgment before seeing AI advice reduces overreliance. Protocol design matters.", "q": "Cognitively costly. Feasible for high-stakes decisions but impractical for routine tasks.", "u": "content/papers/bucinca-2021.html"},
{"t": "Explanations Can Reduce Overreliance on AI Systems", "a": "Vasconcelos, Jörke et al.", "y": 2023, "s": ["ai-agents"], "ev": "mixed", "st": "debated", "v": "Explanations reduce overreliance when cognitive effort of engagement is low relative to stakes. A cost-benefit framework for XAI.", "q": "Five studies. Specific thresholds are likely task-dependent.", "u": "content/papers/vasconcelos-2023.html"},
{"t": "In Search of Verifiability: Explanations Rarely Enable Complementarity", "a": "Fok & Weld", "y": 2023, "s": ["ai-agents"], "ev": "mixed", "st": "debated", "v": "Explanations rarely produce complementary performance. Verifiable explanations are the exception.", "q": "May reflect current explanation designs rather than a fundamental limitation.", "u": "content/papers/fok-2023.html"},
{"t": "The Misinformation Effect of Explanations in Human-AI Collaboration", "a": "Schemmer, Hemmer, Kuehl & Vössing", "y": 2025, "s": ["ai-agents"], "ev": "mixed", "st": "emerging", "v": "Incorrect AI explanations hurt decision quality more than correct explanations help. The damage is asymmetric.", "q": "Tested in limited domains. Magnitude and boundary conditions need broader replication.", "u": "content/papers/schemmer-2025.html"},
{"t": "Metacognition and Uncertainty Communication in Humans and LLMs", "a": "Steyvers & Peters", "y": 2025, "s": ["ai-agents", "uncertainty-communication"], "ev": "mixed", "st": "emerging", "v": "LLMs are reluctant to express uncertainty, likely due to RLHF. Non-experts are especially susceptible to fluent, unhedged output.", "q": "Review and theoretical framework. Empirical predictions laid out but not yet tested.", "u": "content/papers/steyvers-2025.html"},
{"t": "When Combinations of Humans and AI Are Useful", "a": "Vaccaro, Almaatouq & Malone", "y": 2024, "s": ["ai-agents"], "ev": "strong", "st": "emerging", "v": "Meta-analysis: complementarity achieved in a minority of studied conditions. Task difficulty and AI accuracy are the main moderators.", "q": "Publication bias may understate failure rate.", "u": "content/papers/vaccaro-2024.html"},
{"t": "Measuring and Mitigating Overreliance on LLMs", "a": "Collins et al.", "y": 2025, "s": ["ai-agents"], "ev": "mixed", "st": "emerging", "v": "Maps consequences of overreliance from immediate errors to long-term harms: deskilling, erosion of critical thinking.", "q": "Position paper. Long-term harm claims are theoretically motivated but empirically untested.", "u": "content/papers/collins-et-al-2025.html"},
{"t": "Uncertainty-Aware Task Delegation for Human-AI Decision-Making", "a": "Lee et al.", "y": 2025, "s": ["ai-agents", "uncertainty-communication"], "ev": "weak", "st": "emerging", "v": "Distance-based uncertainty scores outperformed probability-based scores for task delegation, yielding 8.2% higher correct decisions.", "q": "Small sample (N=29), single domain (stroke rehabilitation).", "u": "content/papers/lee-et-al-2025.html"},
{"t": "Human Uncertainty in Concept-Based AI Systems", "a": "Collins, Barber, Callaway et al.", "y": 2023, "s": ["ai-agents", "belief-elicitation"], "ev": "mixed", "st": "emerging", "v": "Accounting for human uncertainty in concept interventions improves AI system performance. Most models wrongly assume humans are perfect oracles.", "q": "Limited ecological validity. Promising framework, untested at scale.", "u": "content/papers/collins-2023.html"},
{"t": "Using AI Uncertainty Quantification to Improve Human Decision-Making", "a": "Prabhudesai et al.", "y": 2023, "s": ["ai-agents", "uncertainty-communication"], "ev": "mixed", "st": "emerging", "v": "Visual AI uncertainty quantification improves human accuracy and confidence calibration compared to prediction alone.", "q": "Lab image classification. Real-world generalization not yet tested.", "u": "content/papers/prabhudesai-et-al-2023.html"},
{"t": "A Decision Theoretic Framework for Measuring AI Reliance", "a": "Guo, Wu, Hartline & Hullman", "y": 2024, "s": ["ai-agents", "decision-quality"], "ev": "mixed", "st": "emerging", "v": "Formal framework connecting reliance behavior to decision-theoretic concepts. Distinguishes rational from irrational reliance.", "q": "Theoretical. Empirical validation limited to controlled experiments.", "u": "content/papers/guo-2024.html"},
{"t": "Bending the Automation Bias Curve", "a": "Horowitz & Kahn", "y": 2024, "s": ["ai-agents"], "ev": "mixed", "st": "emerging", "v": "In a 9-country experiment (N=9000), AI background knowledge shows a Dunning-Kruger pattern: low knowledge → aversion, medium → overreliance, high → calibrated.", "q": "Task identification paradigm. Generalization to complex decision-making assumed.", "u": "content/papers/horowitz-2024.html"},

// ── AI Agents ──────────────────────────────────────────────────────────────
{"t": "Effect of Confidence and Explanation on Accuracy and Trust Calibration in AI-Assisted Decision Making", "a": "Zhang, Liao & Bellamy", "y": 2020, "s": ["ai-agents"], "ev": "strong", "st": "canonical", "v": "Confidence scores calibrate trust case-by-case but trust calibration alone does not improve joint accuracy. Humans also need complementary domain knowledge to capitalize on calibrated trust.", "q": "Income-prediction task with crowdworkers; domain expertise is simulated. The trust calibration vs. accuracy gap is the key finding — its generality to expert domains is assumed.", "u": "content/papers/zhang-liao-2020.html"},
{"t": "Towards a Science of Human-AI Decision Making: A Survey of Empirical Studies", "a": "Lai, Chen, Liao, Smith-Renner & Tan", "y": 2021, "s": ["ai-agents"], "ev": "strong", "st": "canonical", "v": "Systematic review of 100+ empirical studies (2018–2021). Documents fragmented methodology, incompatible metrics, and insufficient coverage of non-classification tasks. Calls for common benchmark frameworks.", "q": "Scope bounded to 2018–2021 and selected venues. The field has grown substantially since; many gaps identified are now active research areas.", "u": "content/papers/lai-2021.html"},
{"t": "Consistent Estimators for Learning to Defer to an Expert", "a": "Mozannar & Sontag", "y": 2020, "s": ["ai-agents"], "ev": "strong", "st": "canonical", "v": "Foundational framework for jointly learning a classifier and a deferral rule that routes instances to a human expert. Provides a consistent surrogate loss with theoretical guarantees.", "q": "Expert behavior is modeled from training data — assumes the deployment expert matches the training expert. Real experts are heterogeneous and dynamic.", "u": "content/papers/mozannar-sontag-2020.html"},
{"t": "Manipulating and Measuring Model Interpretability", "a": "Poursabzi-Sangdeh, Goldstein, Hofman, Vaughan & Wallach", "y": 2021, "s": ["ai-agents"], "ev": "strong", "st": "debated", "v": "Pre-registered N=3,800: simpler, more interpretable models did NOT reliably help users follow AI when correct or detect errors. Interpretability as commonly implemented may not achieve its stated goals.", "q": "Tested in one domain (house price prediction). Null result may be specific to how interpretability was operationalized. Does not rule out better-designed XAI.", "u": "content/papers/poursabzi-2021.html"},
{"t": "Bayesian Preference Elicitation with Language Models", "a": "Handa, Gal, Pavlick, Goodman, Andreas, Tamkin & Li", "y": 2024, "s": ["ai-agents", "belief-elicitation"], "ev": "mixed", "st": "emerging", "v": "OPEN framework uses Bayesian Optimal Experimental Design to guide LM question selection for preference elicitation, outperforming pure LM elicitation by tracking uncertainty explicitly.", "q": "Tested in content recommendation — well-structured domain with clear features. Scalability to open-ended, complex preference spaces is unproven.", "u": "content/papers/handa-2024.html"},
{"t": "Human Decision-making is Susceptible to AI-driven Manipulation", "a": "Sabour et al.", "y": 2025, "s": ["ai-agents"], "ev": "mixed", "st": "emerging", "v": "Randomized experiment (N=233): AI agents using psychological persuasion tactics significantly shifted decisions in financial and emotional domains. Strategy-enhanced manipulation was substantially more effective. Participants could not reliably detect manipulation.", "q": "Single-session lab experiment. Manipulative agent's goals were researcher-defined. Long-term adaptation and detection by users are untested.", "u": "content/papers/sabour-2025.html"},
// ── Decision Quality ────────────────────────────────────────────────────────
{"t": "Le comportement de l'homme rationnel devant le risque (The Allais Paradox)", "a": "Allais", "y": 1953, "s": ["decision-quality"], "ev": "strong", "st": "canonical", "v": "First systematic demonstration that expected utility theory fails descriptively. People switch from preferring a certain 1M to preferring a 10M gamble when a common 89% chance of 1M is added to both — violating the independence axiom.", "q": "Original evidence from surveys with hypothetical outcomes. Violations are strongest when one option is certain; attenuate when both options are probabilistic.", "u": "content/papers/allais-1953.html"},
{"t": "The Framing of Decisions and the Psychology of Choice", "a": "Tversky & Kahneman", "y": 1981, "s": ["decision-quality", "attention-salience"], "ev": "strong", "st": "canonical", "v": "Logically equivalent choices framed as gains vs. losses produce opposite risk preferences. Asian disease problem: 72% risk-averse in gain frame; 78% risk-seeking in loss frame — despite identical outcomes.", "q": "Framing effects attenuate with decision-maker sophistication, repeated exposure, and simultaneous presentation of both frames.", "u": "content/papers/tversky-kahneman-1981.html"},
{"t": "Judgment under Uncertainty: Heuristics and Biases", "a": "Tversky & Kahneman", "y": 1974, "s": ["decision-quality", "belief-elicitation", "attention-salience"], "ev": "strong", "st": "canonical", "v": "Identified representativeness, availability, and anchoring as the three primary heuristics generating systematic probability judgment errors. Established the heuristics-and-biases research program.", "q": "The pejorative 'biases' framing has been substantially revised — the ecological rationality critique showed many heuristics are adaptive in natural environments.", "u": "content/papers/tversky-kahneman-1974.html"},
{"t": "Risk Aversion and Expected-Utility Theory: A Calibration Theorem", "a": "Rabin", "y": 2000, "s": ["decision-quality", "risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Mathematical proof: if a person turns down a 50/50 lose $10/gain $11 gamble at any wealth level, EU theory implies they should also decline a 50/50 gamble of losing $100 vs. winning any finite sum. Loss aversion, not diminishing marginal utility, must explain everyday risk aversion.", "q": "Theoretical result. Some EU specifications avoid the absurd implication at the cost of other counterintuitive features.", "u": "content/papers/rabin-2000.html"},
{"t": "Mental Accounting and Consumer Choice", "a": "Thaler", "y": 1985, "s": ["decision-quality", "attention-salience"], "ev": "strong", "st": "canonical", "v": "People organize spending into segregated mental accounts and evaluate transactions within accounts rather than globally, producing silver lining effects, sunk cost effects, and payment decoupling.", "q": "Mental accounting rules for when accounts are created and transferred are poorly specified computationally; the model is more descriptive than predictive.", "u": "content/papers/thaler-1985.html"},
{"t": "Regret in Decision Making under Uncertainty", "a": "Bell", "y": 1982, "s": ["decision-quality"], "ev": "mixed", "st": "canonical", "v": "Anticipated regret — comparing the chosen outcome to the unchosen alternative — modifies choice and explains preference reversals without probability weighting. Provides an alternative normative target to expected utility.", "q": "Only applies when the unchosen outcome is observable. Applies most to visible counterfactual contexts (seeing what you missed).", "u": "content/papers/bell-1982.html"},
// ── Belief Elicitation ──────────────────────────────────────────────────────
{"t": "The Assessment of Prior Distributions in Bayesian Analysis", "a": "Winkler", "y": 1967, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "First systematic treatment of probability elicitation as a methodological problem. Showed different elicitation procedures applied to the same expert produce different prior distributions — the procedure shapes the belief it claims to measure.", "q": "Focused on conjugate families and analytical tractability. Modern conversational and non-expert elicitation contexts require significant adaptation.", "u": "content/papers/winkler-1967.html"},
{"t": "Uncertain Judgements: Eliciting Experts' Probabilities (SHELF)", "a": "O'Hagan et al.", "y": 2006, "s": ["belief-elicitation"], "ev": "strong", "st": "canonical", "v": "The SHELF (Sheffield Elicitation Framework) protocol — the most comprehensive structured procedure for expert probability elicitation. Quantile-based elicitation + parametric fitting + visual feedback reduces expert overconfidence.", "q": "Developed for engineering and clinical contexts with single, well-defined quantities and domain experts. Difficult to scale to non-expert, large-population, conversational elicitation.", "u": "content/papers/ohagan-2006.html"},
{"t": "On Calibration of Modern Neural Networks", "a": "Guo, Pleiss, Sun & Weinberger", "y": 2017, "s": ["belief-elicitation", "ai-agents"], "ev": "strong", "st": "canonical", "v": "Modern deep neural networks are systematically overconfident despite high accuracy. Temperature scaling — dividing logits by a single learned scalar T before softmax — is the most effective post-hoc recalibration method, preserving accuracy while improving calibration.", "q": "Focuses on classification. Calibration for LLMs with open-ended generation is substantially harder and may require domain-specific approaches.", "u": "content/papers/guo-2017.html"},
// ── Uncertainty Communication ───────────────────────────────────────────────
{"t": "Visualizing Uncertainty About the Future", "a": "Spiegelhalter, Pearson & Short", "y": 2011, "s": ["uncertainty-communication"], "ev": "mixed", "st": "canonical", "v": "Science review proposing that false precision is systematically misleading and that communicating uncertainty — even imperfectly — is better than false confidence. Taxonomizes uncertainty types and matches visualization approaches to each.", "q": "Largely normative — proposes what displays should communicate rather than testing behavioral consequences. The comprehension-use gap (Hofman et al. 2020) partially qualifies the recommendations.", "u": "content/papers/spiegelhalter-2011.html"},
{"t": "Subjective Confidence in Forecasts", "a": "Fischhoff & MacGregor", "y": 1982, "s": ["uncertainty-communication", "belief-elicitation"], "ev": "strong", "st": "canonical", "v": "Recipients interpret the same probabilistic forecast differently depending on implicit reference class — whether probability refers to time, area, or forecaster agreement. Chronic misinterpretation predates Gigerenzer et al. (2005) by two decades.", "q": "Studies early-era probability expressions before standardized scales. Modern AI systems using structured output may reduce but not eliminate reference class ambiguity.", "u": "content/papers/fischhoff-1982.html"},
{"t": "Numeric, Verbal, and Visual Formats of Conveying Health Risks", "a": "Lipkus", "y": 2007, "s": ["uncertainty-communication"], "ev": "strong", "st": "canonical", "v": "Review of 30+ studies on risk communication formats. Icon arrays are the most robust format for low-numeracy populations (30–50% of adults). No single format dominates across all audiences and tasks.", "q": "Health communication context. Generalization to AI confidence displays requires attention to domain differences (health risk is binary; AI uncertainty is often continuous).", "u": "content/papers/lipkus-2007.html"},
{"t": "Uncertainty Displays Using Quantile Dotplots or CDFs Improve Transit Decision-Making", "a": "Fernandes, Walls, Munson, Hullman & Kay", "y": 2018, "s": ["uncertainty-communication", "sampling-experience"], "ev": "mixed", "st": "debated", "v": "In incentivized bus arrival decisions, quantile dotplots and CDFs substantially outperformed 95% CI error bars. Error bars produced a deterministic construal error — users treated interval endpoints as hard boundaries rather than uncertainty expressions.", "q": "Transit domain with MTurk workers. CDFs and dotplots both require brief onboarding. Long-term performance across novel tasks is untested.", "u": "content/papers/fernandes-2018.html"},
{"t": "Communicating Uncertainty in Official Economic Statistics", "a": "Manski", "y": 2015, "s": ["uncertainty-communication"], "ev": "mixed", "st": "canonical", "v": "Official statistical agencies systematically suppress uncertainty by reporting point estimates when intervals are warranted. False precision misrepresents epistemic state and distorts downstream decisions — a direct analogue to AI systems that output point predictions without uncertainty.", "q": "Primarily a normative policy argument. Behavioral evidence that interval reporting actually improves policy decisions is thin in this paper.", "u": "content/papers/manski-2015.html"},
{"t": "More Forecasts, More (Decision) Problems: Uncertainty Representations for Multiple Forecasts", "a": "Sarma, Hedayati & Kay", "y": 2025, "s": ["uncertainty-communication", "decision-quality"], "ev": "mixed", "st": "emerging", "v": "Three pre-registered experiments: both p-boxes and ensemble CDFs led to uncertainty-averse decisions (γ≈0.24) when forecasts were uniformly distributed. Ensemble representations are additionally sensitive to forecast distribution — participants followed visual clusters rather than worst-case bounds when most forecasts clustered near one bound.", "q": "Binary decision task in a single domain. Crossover-point bias (optimal 0.2, observed 0.31) likely reflects task calibration, not display effects. Ecological validity of incentivized bonus structure is unknown.", "u": "content/papers/sarma-2025.html"},
{"t": "Multiple Forecast Visualizations (MFVs): Trade-offs in Trust and Performance in Multiple COVID-19 Forecast Visualizations", "a": "Padilla, Fygenson, Castro & Bertini", "y": 2023, "s": ["uncertainty-communication", "sampling-experience"], "ev": "mixed", "st": "emerging", "v": "N=1,299: trust increases with number of forecasts, plateauing at 6–9. The 95% CI is most trusted but produces the worst trend prediction. The trust-accuracy inversion: simpler displays are trusted more but support less accurate judgments about the underlying data.", "q": "Real COVID-19 data adds ecological validity but also confounds — some models happen to be more accurate. Single-country US sample. Trust measured by self-report slider.", "u": "content/papers/padilla-2023.html"},
// ── Attention & Salience ────────────────────────────────────────────────────
{"t": "Attention and Effort", "a": "Kahneman", "y": 1973, "s": ["attention-salience"], "ev": "strong", "st": "canonical", "v": "Established attention as a limited, allocable cognitive resource. Pupillary dilation as a real-time mental effort measure. Dual-task interference scales with attentional demand of each task. Foundation for all subsequent cognitive load theory and dual-process models.", "q": "Single-resource model has been refined — multiple-resource theories now distinguish visual, auditory, spatial, and verbal channels with partially independent capacities.", "u": "content/papers/kahneman-1973.html"},
{"t": "Does Living in California Make People Happy? A Focusing Illusion in Judgments of Life Satisfaction", "a": "Schkade & Kahneman", "y": 1998, "s": ["attention-salience", "decision-quality"], "ev": "strong", "st": "canonical", "v": "When evaluating satisfaction, the salient attribute becomes the focal object and is systematically overweighted. 'Nothing is as important as you think it is while you are thinking about it.' AI interfaces that direct attention to specific attributes implicitly determine what users think matters most.", "q": "Between-subjects design; within-person focusing effects may be smaller if people can adjust for the irrelevant attribute.", "u": "content/papers/schkade-1998.html"},
{"t": "Salience and Consumer Choice", "a": "Bordalo, Gennaioli & Shleifer", "y": 2013, "s": ["attention-salience", "decision-quality"], "ev": "mixed", "st": "debated", "v": "Extension of salience theory to consumer markets. Attributes that stand out relative to the choice set average are overweighted. Predicts asymmetric price and quality sensitivities and the decoy effect through a single mechanism.", "q": "Theoretical model fitted to stylized evidence. Distinguishing salience from reference-dependence in field data is difficult without experimental variation.", "u": "content/papers/bordalo-2013.html"},
{"t": "Brand Choice Behavior as a Function of Information Load", "a": "Jacoby, Speller & Kohn", "y": 1974, "s": ["attention-salience", "uncertainty-communication"], "ev": "mixed", "st": "canonical", "v": "Information overload: decision quality shows an inverted-U with number of attributes. Subjective confidence increases monotonically even as objective decision quality declines beyond 4–8 attributes — users feel better informed but make worse choices.", "q": "Methodologically contested; subsequent replications found more modest overload thresholds. Effect size is sensitive to information structure and task type.", "u": "content/papers/jacoby-1974.html"},
// ── Risk & Ambiguity ────────────────────────────────────────────────────────
{"t": "Risk, Uncertainty and Profit", "a": "Knight", "y": 1921, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "First formal distinction between risk (known probability distribution) and Knightian uncertainty (no probability can be assigned). AI models operating out-of-distribution face Knightian uncertainty, not risk — presenting AI confidence scores as if they were calibrated risks is a fundamental framing error.", "q": "Pre-formal economics. The risk/uncertainty boundary is conceptually clear but operationally fuzzy — knowing when you don't have a probability is itself uncertain.", "u": "content/papers/knight-1921.html"},
{"t": "Subjective Probability and Expected Utility without Additivity", "a": "Schmeidler", "y": 1989, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Choquet Expected Utility: a generalization of EU that allows non-additive beliefs, accommodating ambiguity aversion through a convex capacity that underweights uncertain events. Mathematically unifies ambiguity aversion without requiring a set of priors.", "q": "Empirically difficult — the non-additive capacity has many degrees of freedom not identifiable from choice data without strong parametric assumptions.", "u": "content/papers/schmeidler-1989.html"},
{"t": "Making Decisions under Model Misspecification", "a": "Cerreia-Vioglio, Hansen, Maccheroni & Marinacci", "y": 2022, "s": ["risk-ambiguity", "decision-quality"], "ev": "mixed", "st": "emerging", "v": "Extends max-min EU to settings where the decision maker knows all candidate models are approximations (misspecified). The misspecification fear parameter λ controls weight on model-violating scenarios. Directly relevant to AI-assisted decisions where model confidence reflects training distribution, not deployment reality.", "q": "Axiomatic theory paper. Empirical identification of misspecification fear vs. ambiguity aversion from behavioral data is an open problem.", "u": "content/papers/cerreia-vioglio-2022.html"},
{"t": "Ambiguity Aversion, Robustness, and the Variational Representation of Preferences", "a": "Maccheroni, Marinacci & Rustichini", "y": 2006, "s": ["risk-ambiguity"], "ev": "strong", "st": "canonical", "v": "Variational preferences unify max-min EU, multiplier preferences, and mean-variance preferences under a single axiomatic framework via a cost function penalizing deviations from a reference prior.", "q": "Highly technical. Empirical identification of the cost function from behavioral data requires strong parametric restrictions. Primarily applied in macroeconomics and asset pricing.", "u": "content/papers/maccheroni-2006.html"},
{"t": "Ellsberg Revisited: An Experimental Study", "a": "Halevy", "y": 2007, "s": ["risk-ambiguity"], "ev": "mixed", "st": "debated", "v": "Demonstrates that most Ellsberg-type behavior is associated with failure to reduce compound lotteries — treating a two-stage lottery differently from its single-stage equivalent even with fully specified probabilities. Challenges whether dedicated ambiguity models are necessary.", "q": "The identification of ambiguity aversion with compound lottery non-reduction is contested. Some authors argue both mechanisms are real and empirically dissociable.", "u": "content/papers/halevy-2007.html"},
// ── Temporal Dynamics ───────────────────────────────────────────────────────
{"t": "Specious Reward: A Behavioral Theory of Impulsiveness and Impulse Control", "a": "Ainslie", "y": 1975, "s": ["temporal-dynamics"], "ev": "strong", "st": "canonical", "v": "First systematic argument that hyperbolic discounting characterizes intertemporal choice. Hyperbolic curves produce preference reversals as delay shortens — the same person prefers the larger-later reward when both are distant, then switches to the smaller-sooner reward when it becomes imminent.", "q": "Primarily from animal learning literature. Human hyperbolic discounting has been extensively documented but the normative status of the reversal is debated.", "u": "content/papers/ainslie-1975.html"},
{"t": "Anomalies in Intertemporal Choice: Evidence and an Interpretation", "a": "Loewenstein & Prelec", "y": 1992, "s": ["temporal-dynamics"], "ev": "strong", "st": "canonical", "v": "Documented four systematic violations of exponential discounting and provided a generalized hyperbolic functional form. The four anomalies: hyperbolic discount rates, absolute magnitude effects, delay/speedup asymmetry, and the sign effect (gains discounted more than losses).", "q": "Most evidence from hypothetical monetary choices. Incentive-compatible studies find smaller but qualitatively similar effects.", "u": "content/papers/loewenstein-prelec-1992.html"},
{"t": "Doing It Now or Later", "a": "O'Donoghue & Rabin", "y": 1999, "s": ["temporal-dynamics"], "ev": "strong", "st": "canonical", "v": "Formalized β-δ present-biased preferences and introduced the sophisticated vs. naïve distinction. Sophisticated agents know they are present-biased and use commitment devices; naïve agents underestimate their future bias and chronically procrastinate.", "q": "The sophistication vs. naïvety distinction is empirically difficult to measure — most studies cannot identify which type they are observing.", "u": "content/papers/odonoghue-rabin-1999.html"},
{"t": "Time Discounting and Time Preference: A Critical Review", "a": "Frederick, Loewenstein & O'Donoghue", "y": 2002, "s": ["temporal-dynamics"], "ev": "strong", "st": "canonical", "v": "Definitive review showing that measured discount rates are not stable individual traits — they vary dramatically by domain, stakes, gain/loss framing, and elicitation method. A person cannot be characterized by a single discount rate applicable across contexts.", "q": "Primarily a survey. The main finding — discount rate instability — limits any personalization approach that infers time preferences from limited behavioral data.", "u": "content/papers/frederick-2002.html"},
// ── Sampling & Experience ───────────────────────────────────────────────────
{"t": "Small Feedback-Based Decisions and Their Limited Correspondence with Description-Based Decisions", "a": "Barron & Erev", "y": 2003, "s": ["sampling-experience"], "ev": "strong", "st": "canonical", "v": "Original description-experience gap paper. When outcomes are discovered by sampling rather than described numerically, rare events are underweighted rather than overweighted — reversing the prospect theory prediction. Most AI interfaces operate in description mode.", "q": "The underweighting is partly explained by sampling error — participants who never observe a rare event treat it as zero probability. Fox & Hadar (2006) showed the residual gap after controlling for information is smaller.", "u": "content/papers/barron-erev-2003.html"},
{"t": "Are Probabilities Overweighted or Underweighted When Rare Outcomes Are Experienced (Rarely)?", "a": "Ungemach, Chater & Stewart", "y": 2009, "s": ["sampling-experience", "decision-quality"], "ev": "mixed", "st": "debated", "v": "When experience-based choices are analyzed using the probability actually observed in the participant's sample, much of the apparent underweighting disappears. The description-experience gap is substantially a consequence of sampling error, not a different probability weighting function.", "q": "The residual gap after controlling for sample information is debated — Hertwig & Erev (2009) and Camilleri & Newell (2011) find a genuine gap persists.", "u": "content/papers/ungemach-2009.html"},
{"t": "Adaptive Learning from Sequential Choice", "a": "Hills, Noguchi & Gibbert", "y": 2013, "s": ["sampling-experience", "attention-salience"], "ev": "mixed", "st": "debated", "v": "Proposes that the direction of experience-based biases depends on the statistical structure of the natural environment. Recency-weighting of outcomes is an ecologically rational heuristic in environments with autocorrelated resources, but produces underweighting of rare events in lab gambles with independent outcomes.", "q": "Framework is largely theoretical. Operationalizing 'natural environment statistics' for financial or medical decisions is underspecified.", "u": "content/papers/hills-2013.html"},
{"t": "The Hot Hand in Basketball: On the Misperception of Random Sequences", "a": "Gilovich, Vallone & Tversky", "y": 1985, "s": ["sampling-experience", "belief-elicitation"], "ev": "strong", "st": "debated", "v": "Classic demonstration that perceived streaks in shot sequences are statistically indistinguishable from random. Miller & Sanjurjo (2018) later showed the original analysis had a systematic bias, and corrected analyses suggest genuine hot hand effects in some datasets.", "q": "The Miller & Sanjurjo correction is now widely accepted. The hot hand question remains empirically open — the original 'no hot hand' conclusion was too strong.", "u": "content/papers/gilovich-1985.html"},
];
const STREAM_COLORS={"belief-elicitation": "#3572A5", "uncertainty-communication": "#2A9D8F", "decision-quality": "#E76F51", "attention-salience": "#9B59B6", "risk-ambiguity": "#DC4C64", "temporal-dynamics": "#2E86AB", "sampling-experience": "#D4A017", "ai-agents": "#264653"};
const EV_CLASS={"strong":"ev-strong","mixed":"ev-mixed","weak":"ev-weak"};
const ST_CLASS={"canonical":"st-canonical","debated":"st-debated","emerging":"st-emerging"};